fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();

    // Create the first output matrix with repeated rows of x
    let x_grid = vec![x.clone(); rows];

    // Create the second output matrix with repeated columns of y
    let mut y_grid = vec![vec![0.0; cols]; rows];
    for i in 0..rows {
        for j in 0..cols {
            y_grid[i][j] = y[i];
        }
    }

    (x_grid, y_grid)
}

fn main() {
    let x = vec![1.0, 2.0, 3.0];
    let y = vec![4.0, 5.0];
    
    let (x_grid, y_grid) = meshgrid(x, y);
    
    println!("X Grid: {:?}", x_grid);
    println!("Y Grid: {:?}", y_grid);
}